// Lookup: поиск лида в Zoho по телефону (варианты номера) или по имени (word search)
const q = $json.query || {};
const term = String(q.lookup || '').trim().slice(0, 80);
const digits = term.replace(/\D/g, '');
let dealsUrl, contactsUrl;

if (digits.length >= 7 && digits.length >= term.replace(/[\s()+.\-]/g, '').length - 1) {
  const variants = new Set();
  if (digits.length === 10) {
    ['+1' + digits, digits, '1' + digits].forEach(v => variants.add(v));
  } else if (digits.length === 11 && digits.startsWith('1')) {
    const n = digits.slice(1);
    ['+1' + n, n, digits, '+' + digits].forEach(v => variants.add(v));
  } else {
    variants.add(digits);
    variants.add('+' + digits);
  }
  const crit = '(' + [...variants].map(v => `(Phone:equals:${v})`).join('or') + ')';
  const enc = encodeURIComponent(crit);
  dealsUrl = `https://www.zohoapis.com/crm/v2/Deals/search?criteria=${enc}&per_page=20`;
  contactsUrl = `https://www.zohoapis.com/crm/v2/Contacts/search?criteria=${enc}&per_page=20`;
} else {
  const word = encodeURIComponent(term);
  dealsUrl = `https://www.zohoapis.com/crm/v2/Deals/search?word=${word}&per_page=20`;
  contactsUrl = `https://www.zohoapis.com/crm/v2/Contacts/search?word=${word}&per_page=20`;
}

return [{ json: { dealsUrl, contactsUrl, term } }];

// Сводим результаты поиска Deals + Contacts в детальные карточки (все непустые поля)
const dealsResp = $('Zoho: Lookup Deals').first().json || {};
const contactsResp = $input.first().json || {};

const clean = (rec) => {
  const out = {};
  for (const [k, v] of Object.entries(rec)) {
    if (k.startsWith('$')) continue;
    if (v === null || v === undefined || v === '') continue;
    if (Array.isArray(v)) {
      if (v.length) out[k] = v.map(x => (x && (x.name || x.id)) || x).join(', ');
    } else if (typeof v === 'object') {
      if (v.name) out[k] = v.name;
      else if (v.id) out[k] = v.id;
    } else {
      out[k] = v;
    }
  }
  return out;
};
const pickErr = (resp) => {
  if (resp.error) return String(resp.error.message || resp.error.description || JSON.stringify(resp.error)).slice(0, 200);
  if (resp.code && resp.message) return (resp.code + ' ' + resp.message).slice(0, 200);
  return '';
};

const deals = (Array.isArray(dealsResp.data) ? dealsResp.data : []).map(clean);
const contacts = (Array.isArray(contactsResp.data) ? contactsResp.data : []).map(clean);
const error = pickErr(dealsResp) || pickErr(contactsResp);

return [{
  json: {
    ok: !error,
    error,
    term: $('Build Lookup').first().json.term,
    deals,
    contacts,
  },
}];

// Вид "Via Dashboard": вся история дашборд-лидов из журнала Google Sheets
const items = $input.all();
const q = $('Webhook').first().json.query || {};
let error = '';
let leads = [];
for (const it of items) {
  const j = it.json || {};
  if (j.error) {
    const e = j.error;
    error = 'Journal sheet error: ' + String(e.message || e.description || JSON.stringify(e)).slice(0, 200)
      + " — check that the 'Dashboard Leads' tab exists";
    continue;
  }
  if (!j['Added'] && !j['Phone'] && !j['First Name']) continue;
  leads.push({
    added: j['Added'] || '',
    first_name: j['First Name'] || '',
    last_name: j['Last Name'] || '',
    phone: j['Phone'] || '',
    email: j['Email'] || '',
    city: j['City'] || '',
    zip: j['ZIP'] || '',
    contact_time: j['Contact Time'] || '',
    source: j['Source'] || '',
    status: j['Status'] || '',
    deal_stage: j['Deal Stage'] || '',
    deal_id: j['Deal ID'] || '',
    via_dashboard: true,
  });
}
leads.sort((a, b) => String(b.added).localeCompare(String(a.added)));
const search = String(q.search || '').trim().toLowerCase();
if (search) leads = leads.filter(l => JSON.stringify(l).toLowerCase().includes(search));
const limit = parseInt(q.limit, 10);
if (Number.isFinite(limit) && limit > 0) leads = leads.slice(0, limit);

return [{ json: { ok: !error, error, count: leads.length, leads } }];

// Приводим ответ GET /crm/v2/Deals к плоскому массиву лидов для дашборда
const resp = $input.first().json || {};
const q = $('Webhook').first().json.query || {};
let rows = Array.isArray(resp.data) ? resp.data : [];
let error = '';
if (!Array.isArray(resp.data) && Object.keys(resp).length > 0) {
  if (resp.error) {
    const e = resp.error;
    error = 'Zoho: ' + String(e.message || e.description || (typeof e === 'string' ? e : JSON.stringify(e))).slice(0, 300);
  } else if (resp.message || resp.code) {
    error = ('Zoho: ' + (resp.code || '') + ' ' + (resp.message || '')).trim();
  }
}
let leads = rows.map(r => {
  let added = '';
  if (r.Created_Time) {
    const dt = DateTime.fromISO(r.Created_Time).setZone('America/New_York');
    added = dt.isValid ? dt.toFormat('yyyy-MM-dd HH:mm') : String(r.Created_Time);
  }
  const contactName = (r.Contact_Name && r.Contact_Name.name) || '';
  let first = '', last = '';
  const nameSrc = contactName || r.Deal_Name || '';
  if (nameSrc) {
    const parts = String(nameSrc).trim().split(/\s+/);
    first = parts.shift() || '';
    last = parts.join(' ');
  }
  return {
    added,
    first_name: first,
    last_name: last,
    phone: r.Phone || '',
    zip: r.Zip_Code || '',
    contact_time: r.Best_Contact_Time || '',
    source: r.Lead_Source || '',
    status: r.Stage || '',
    deal_stage: r.Stage || '',
    deal_id: r.id || '',
    via_dashboard: /Added via Dashboard/i.test(String(r.Description || '')),
  };
});
const search = String(q.search || '').trim().toLowerCase();
if (search) leads = leads.filter(l => JSON.stringify(l).toLowerCase().includes(search));
const limit = parseInt(q.limit, 10);
if (Number.isFinite(limit) && limit > 0) leads = leads.slice(0, limit);

return [{ json: { ok: !error, error, count: leads.length, leads } }];
